package gen:node;

world node {
    use aap:caps/types@0.1.0.{feed-item};

    import aap:caps/state-read@0.1.0;

    export run: func(items: list<feed-item>) -> list<feed-item>;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // DropSeen: keep only items we have not recorded as seen before.
        //
        // The 'seen' store is addressed by item id. `id` is a parser-computed
        // digest, never a string the feed chose, so it is safe as a store key.
        // Read-only: StateHandle<'seen', read> exposes only `get`, so this node
        // cannot change what the next run sees.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
```

